/bin/bash -lc "python - <<'PY'
import pathlib,re
for f in sorted(pathlib.Path('.').glob('*.txt')):
 s=f.read_text(); pages=re.split(r'--- page (\\d+) ---',s)
 print('\\nFILE',f.name)
 for i in range(1,len(pages),2):
  p,t=pages[i:i+2]; lines=t.splitlines(); ids=set()
  for j,l in enumerate(lines):
   if re.search(r'compet|exclusiv|shall not|will not|agrees not|may not|non.?circum',l,re.I):
    if re.search(r'competent|jurisdiction|exclusive remed|non-exclusive|nonexclusive|sole and exclusive|complete and exclusive',l,re.I):continue
    ids.update(range(max(0,j-1),min(len(lines),j+4)))
  if ids:
   print('PAGE',p)
   print('\\n'.join(lines[j] for j in sorted(ids)))
PY"

