import pathlib,re
for f in sorted(pathlib.Path('.').glob('*.txt')):
 s=f.read_text();
 if re.search(r'compet(?"'!ent|ence)'"',s,re.I) and not f.name.startswith(('NANOPHASE','USASYNTHETIC')):continue
 print('\\nFILE',f.name)
 for m in re.finditer(r'["'^'"\\n]*(?:shall not|will not|agrees not|exclusiv|restrict|prohibit)["'^'"\\n]*',s,re.I):
  print(s[max(0,m.start()-100):min(len(s),m.end()+250)].replace('\\n',' '))
